 void buildRecord(){ScrollView sv=new ScrollView(this);LinearLayout p=new LinearLayout(this);p.setOrientation(LinearLayout.VERTICAL);p.setPadding(0,dp(10),0,0);sv.addView(p);sid=new EditText(this);sid.setHint("Session ID, e.g. S01_rest_supine");sid.setSingleLine(true);p.addView(sid);note=new EditText(this);note.setHint("Notes: phone position, posture, reference device");note.setMinLines(3);p.addView(note);p.addView(tv("Sampling mode for MAG, ACC and GYRO",13,Color.rgb(71,85,105)));rate=new Spinner(this);String[] m={"50 Hz","100 Hz","200 Hz","Maximum"};ArrayAdapter<String>a=new ArrayAdapter<String>(this,android.R.layout.simple_spinner_item,m);a.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);rate.setAdapter(a);rate.setSelection(2);p.addView(rate);LinearLayout row=new LinearLayout(this);row.setOrientation(LinearLayout.HORIZONTAL);start=new Button(this);start.setText("START");stop=new Button(this);stop.setText("STOP");stop.setEnabled(false);save1=new Button(this);save1.setText("SAVE CSV");save1.setEnabled(false);row.addView(start,new LinearLayout.LayoutParams(0,dp(54),1));row.addView(stop,new LinearLayout.LayoutParams(0,dp(54),1));row.addView(save1,new LinearLayout.LayoutParams(0,dp(54),1));p.addView(row);stat=tv("Ready. Start recording, then open MAG, ACC or GYRO tab.",15,Color.rgb(51,65,85));p.addView(stat);p.addView(tv("CSV uses event-based rows, so ACC and GYRO are saved at their own timestamps, not downsampled to MAG.",13,Color.rgb(100,116,139)));start.setOnClickListener(v->go());stop.setOnClickListener(v->halt());save1.setOnClickListener(v->saveCsv());recordTab=panel(sv);} 
