 boolean sensors(){if(sm!=null&&mag!=null)return true;sm=(SensorManager)getSystemService(SENSOR_SERVICE);if(sm==null){stat.setText("Sensor service unavailable");return false;}mag=sm.getDefaultSensor(Sensor.TYPE_MAGNETIC_FIELD);if(mag==null)mag=sm.getDefaultSensor(Sensor.TYPE_MAGNETIC_FIELD_UNCALIBRATED);la=sm.getDefaultSensor(Sensor.TYPE_LINEAR_ACCELERATION);gy=sm.getDefaultSensor(Sensor.TYPE_GYROSCOPE);if(mag==null){stat.setText("No magnetometer found");return false;}meta.setText("App version: 6.3\nMAG: "+name(mag)+"\nACC: "+name(la)+"\nGYRO: "+name(gy)+"\nMode: "+mode());return true;} String name(Sensor s){return s==null?"not available":s.getName();}
 int del(){int p=rate.getSelectedItemPosition();if(p==0)return 20000;if(p==1)return 10000;if(p==2)return 5000;return SensorManager.SENSOR_DELAY_FASTEST;} String mode(){return String.valueOf(rate.getSelectedItem());} float ts(long ns){if(t0<0)t0=ns;return (ns-t0)/1000000000f;}
 void go(){if(!sensors())return;rows.clear();bxP.cl();byP.cl();bzP.cl();baP.cl();axP.cl();ayP.cl();azP.cl();gxP.cl();gyP.cl();gzP.cl();t0=-1;lastMag=-1;lastAcc=-1;lastGyro=-1;wall=System.currentTimeMillis();rec=true;start.setEnabled(false);stop.setEnabled(true);save1.setEnabled(false);save2.setEnabled(false);sid.setEnabled(false);note.setEnabled(false);rate.setEnabled(false);int d=del();sm.unregisterListener(this);boolean ok=sm.registerListener(this,mag,d);if(la!=null)sm.registerListener(this,la,d);if(gy!=null)sm.registerListener(this,gy,d);if(!ok){stat.setText("Could not start magnetometer");halt();return;}stat.setText("Recording at "+mode()+". Use MAG, ACC or GYRO tabs to view signals.");show(1);} 
 void halt(){rec=false;if(sm!=null)sm.unregisterListener(this);start.setEnabled(true);stop.setEnabled(false);boolean ok=rows.size()>0;save1.setEnabled(ok);save2.setEnabled(ok);sid.setEnabled(true);note.setEnabled(true);rate.setEnabled(true);stat.setText("Stopped. Events: "+rows.size()+". Save from Record or Export tab.");}
 public void onSensorChanged(SensorEvent e){if(e==null||e.values==null||e.values.length<3)return;int typ=e.sensor.getType();float t=ts(e.timestamp);if(typ==Sensor.TYPE_LINEAR_ACCELERATION){float dt=lastAcc>0?(e.timestamp-lastAcc)/1000000f:Float.NaN;lastAcc=e.timestamp;ax=e.values[0];ay=e.values[1];az=e.values[2];if(rec){rows.add(new R("acc",t,e.timestamp,Float.NaN,Float.NaN,Float.NaN,Float.NaN,ax,ay,az,Float.NaN,Float.NaN,Float.NaN,ma,aa,ga,dt));axP.add(t,ax);ayP.add(t,ay);azP.add(t,az);}return;}if(typ==Sensor.TYPE_GYROSCOPE){float dt=lastGyro>0?(e.timestamp-lastGyro)/1000000f:Float.NaN;lastGyro=e.timestamp;gx=e.values[0];gyv=e.values[1];gz=e.values[2];if(rec){rows.add(new R("gyro",t,e.timestamp,Float.NaN,Float.NaN,Float.NaN,Float.NaN,Float.NaN,Float.NaN,Float.NaN,gx,gyv,gz,ma,aa,ga,dt));gxP.add(t,gx);gyP.add(t,gyv);gzP.add(t,gz);}return;}if(typ!=Sensor.TYPE_MAGNETIC_FIELD&&typ!=Sensor.TYPE_MAGNETIC_FIELD_UNCALIBRATED)return;float dt=lastMag>0?(e.timestamp-lastMag)/1000000f:Float.NaN;lastMag=e.timestamp;bx=e.values[0];by=e.values[1];bz=e.values[2];ba=(float)Math.sqrt(bx*bx+by*by+bz*bz);if(rec){rows.add(new R("mag",t,e.timestamp,bx,by,bz,ba,Float.NaN,Float.NaN,Float.NaN,Float.NaN,Float.NaN,Float.NaN,ma,aa,ga,dt));bxP.add(t,bx);byP.add(t,by);bzP.add(t,bz);baP.add(t,ba);}}
 public void onAccuracyChanged(Sensor s,int a){if(s==null)return;int t=s.getType();if(t==Sensor.TYPE_LINEAR_ACCELERATION)aa=a;else if(t==Sensor.TYPE_GYROSCOPE)ga=a;else ma=a;}
 void upd(){float dur=t0>=0?(SystemClock.elapsedRealtimeNanos()-t0)/1000000000f:0;if(read!=null)read.setText(String.format(Locale.US,"MAG\nBx %.2f  By %.2f  Bz %.2f  |B| %.2f uT\n\nLinear ACC without gravity\nAx %.3f  Ay %.3f  Az %.3f m/s2\n\nGYRO\nGx %.3f  Gy %.3f  Gz %.3f rad/s\n\nEvents %d   Duration %.1f s   Mode %s",bx,by,bz,ba,ax,ay,az,gx,gyv,gz,rows.size(),dur,mode()));}
 void saveCsv(){if(rows.isEmpty()){Toast.makeText(this,"No samples to save",Toast.LENGTH_SHORT).show();return;}String id=clean(sid.getText().toString());if(id.length()==0)id="session";String st=new SimpleDateFormat("yyyyMMdd_HHmmss",Locale.US).format(new Date(wall>0?wall:System.currentTimeMillis()));Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("text/csv");i.putExtra(Intent.EXTRA_TITLE,"mag_v6_3_"+id+"_"+st+".csv");startActivityForResult(i,CSV);} protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(r==CSV&&c==RESULT_OK&&d!=null&&d.getData()!=null){try{OutputStream o=getContentResolver().openOutputStream(d.getData());BufferedWriter w=new BufferedWriter(new OutputStreamWriter(o,StandardCharsets.UTF_8));w.write(csvText());w.close();Toast.makeText(this,"CSV saved",Toast.LENGTH_LONG).show();}catch(Exception e){Toast.makeText(this,"Save failed: "+e.getMessage(),Toast.LENGTH_LONG).show();}}}
 String csvText(){StringBuilder sb=new StringBuilder();sb.append("# app_version,6.3\n# ui_layout,signal_tabs_mag_acc_gyro\n# sampling_mode,").append(mode()).append("\n# requested_delay_us,").append(del()).append("\n# subject,").append(csv(sid.getText().toString())).append("\n# notes,").append(csv(note.getText().toString())).append("\n# device,").append(csv(Build.MANUFACTURER+" "+Build.MODEL)).append("\n# event_count,").append(rows.size()).append("\n");sb.append("sensor_type,time_s,timestamp_ns,system_start_unix_ms,Bx_uT,By_uT,Bz_uT,B_abs_uT,linacc_x_mps2,linacc_y_mps2,linacc_z_mps2,gyro_x_rad_s,gyro_y_rad_s,gyro_z_rad_s,mag_accuracy,linacc_accuracy,gyro_accuracy,dt_ms\n");for(R s:rows)sb.append(String.format(Locale.US,"%s,%.9f,%d,%d,%.9f,%.9f,%.9f,%.9f,%.9f,%.9f,%.9f,%.9f,%.9f,%.9f,%d,%d,%d,%.6f\n",s.type,s.t,s.ns,wall,s.bx,s.by,s.bz,s.ba,s.ax,s.ay,s.az,s.gx,s.gy,s.gz,s.ma,s.aa,s.ga,s.dt));return sb.toString();}
 static String clean(String s){return s==null?"":s.trim().replaceAll("[^A-Za-z0-9_.-]+","_");} static String csv(String s){if(s==null)return"";boolean q=s.contains(",")||s.contains("\n")||s.contains("\"");String e=s.replace("\"","\"\"").replace("\r"," ").replace("\n"," ");return q?"\""+e+"\"":e;} int dp(int v){return(int)(v*getResources().getDisplayMetrics().density+.5f);} LinearLayout.LayoutParams sz(){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(240));p.setMargins(0,dp(8),0,dp(8));return p;}
 static class R{String type;float t,bx,by,bz,ba,ax,ay,az,gx,gy,gz,dt;long ns;int ma,aa,ga;R(String type,float t,long ns,float bx,float by,float bz,float ba,float ax,float ay,float az,float gx,float gy,float gz,int ma,int aa,int ga,float dt){this.type=type;this.t=t;this.ns=ns;this.bx=bx;this.by=by;this.bz=bz;this.ba=ba;this.ax=ax;this.ay=ay;this.az=az;this.gx=gx;this.gy=gy;this.gz=gz;this.ma=ma;this.aa=aa;this.ga=ga;this.dt=dt;}}
 public static class P extends View{ArrayDeque<float[]>q=new ArrayDeque<>();Paint bg=new Paint(1),b=new Paint(1),g=new Paint(1),tx=new Paint(1),ln=new Paint(1);String title,ylab;P(Context c,String t,String y,int col){super(c);title=t;ylab=y;bg.setColor(Color.WHITE);b.setColor(Color.rgb(75,85,99));b.setStyle(Paint.Style.STROKE);b.setStrokeWidth(2);g.setColor(Color.rgb(226,232,240));tx.setColor(Color.rgb(55,65,81));tx.setTextSize(22);ln.setColor(col);ln.setStrokeWidth(3);setBackgroundColor(Color.rgb(246,248,252));}void cl(){q.clear();invalidate();}void add(float t,float v){q.add(new float[]{t,v});while(q.size()>700)q.removeFirst();postInvalidateOnAnimation();}protected void onDraw(Canvas c){super.onDraw(c);int w=getWidth(),h=getHeight();float l=86,T=38,r=w-22,bt=h-68;c.drawRect(0,0,w,h,bg);c.drawText(title,l,27,tx);c.drawRect(l,T,r,bt,b);for(int i=1;i<4;i++){float yy=T+i*(bt-T)/4;c.drawLine(l,yy,r,yy,g);}c.drawText(ylab,6,T+18,tx);if(q.size()<2){String xl="Time (s)";c.drawText(xl,(l+r-tx.measureText(xl))/2,h-10,tx);c.drawText("Waiting for samples...",l+12,T+48,tx);return;}float t0=q.peekFirst()[0],t1=q.peekLast()[0];if(t1<=t0)t1=t0+1;float mn=Float.POSITIVE_INFINITY,mx=Float.NEGATIVE_INFINITY;for(float[]p:q){float v=p[1];if(!Float.isNaN(v)&&!Float.isInfinite(v)){mn=Math.min(mn,v);mx=Math.max(mx,v);}}if(Math.abs(mx-mn)<1e-6){mn-=1;mx+=1;}float pad=.1f*(mx-mn);mn-=pad;mx+=pad;c.drawText(String.format(Locale.US,"%.1f",mx),6,T+38,tx);c.drawText(String.format(Locale.US,"%.1f",mn),6,bt,tx);String leftT=String.format(Locale.US,"%.1fs",t0),rightT=String.format(Locale.US,"%.1fs",t1),xlab="Time (s)";float tickY=h-34,axisY=h-10;c.drawText(leftT,l,tickY,tx);c.drawText(rightT,r-tx.measureText(rightT),tickY,tx);c.drawText(xlab,(l+r-tx.measureText(xlab))/2,axisY,tx);Float lx=null,ly=null;for(float[]p:q){float x=l+(r-l)*(p[0]-t0)/(t1-t0);float y=bt-(bt-T)*(p[1]-mn)/(mx-mn);if(lx!=null)c.drawLine(lx,ly,x,y,ln);lx=x;ly=y;}}}
